import { createContext, useContext, useReducer } from "react";

const PRODUCTS = [
  { id: 1, name: "Áo", price: 100 },
  { id: 2, name: "Quần", price: 250 },
];

function reducer(state, action) {
  switch (action.type) {
    case "add": {
      const found = state.find((l) => l.id === action.id);
      return found
        ? state.map((l) => (l.id === action.id ? { ...l, qty: l.qty + 1 } : l))
        : [...state, { id: action.id, qty: 1 }];
    }
    case "remove":
      return state.filter((l) => l.id !== action.id);
    default:
      return state;
  }
}

const CartCtx = createContext(null);
const useCart = () => useContext(CartCtx);

function CartProvider({ children }) {
  const [lines, dispatch] = useReducer(reducer, []);
  return <CartCtx.Provider value={{ lines, dispatch }}>{children}</CartCtx.Provider>;
}

function Shop() {
  const { dispatch } = useCart();
  return (
    <ul>
      {PRODUCTS.map((p) => (
        <li key={p.id}>
          {p.name} - {p.price}
          <button id={"add" + p.id} onClick={() => dispatch({ type: "add", id: p.id })}>Thêm</button>
        </li>
      ))}
    </ul>
  );
}

function Cart() {
  const { lines, dispatch } = useCart();
  const total = lines.reduce((s, l) => s + PRODUCTS.find((p) => p.id === l.id).price * l.qty, 0);   // DẪN XUẤT
  const count = lines.reduce((s, l) => s + l.qty, 0);
  return (
    <div>
      <p id="count">{count}</p>
      <p id="total">{total}</p>
      {lines.map((l) => (
        <button key={l.id} id={"rm" + l.id} onClick={() => dispatch({ type: "remove", id: l.id })}>Xoá {l.id}</button>
      ))}
    </div>
  );
}

export default function App() {
  return (
    <CartProvider>
      <Shop />
      <Cart />
    </CartProvider>
  );
}

